import{_ as n,l as r,o as a,c as l,v as s,p as o,x as t,d as c,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"Rust in kernel","description":"","frontmatter":{"title":"Rust in kernel","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rust-in-kernel.md","filePath":"cs/rust-in-kernel.md","lastUpdated":1789023840000}'),p={name:"cs/rust-in-kernel.md"};function h(f,e,k,_,m,A){const i=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=s('<h1 id="rust-in-kernel" tabindex="-1">Rust in kernel <a class="header-anchor" href="#rust-in-kernel" aria-label="Permalink to &quot;Rust in kernel&quot;">​</a></h1><div class="epigraph"><p>Linux 允许用 Rust 写部分驱动与子系统：借用检查在编译期排除一类空间错误，FFI 仍与 C 内核对话，panic 策略必须适合内核。</p><footer>—— 据 Linux Rust 文档；[ASan](/cs/asan-mechanism) 与 [MTE](/cs/memory-tagging) 为运行时对照；[kABI](/cs/kabi-module-signing) 为绑定</footer></div><p><a href="/cs/exokernel-libos">外核</a> 改架构。缺口是 <strong>在宏内核里换语言</strong>：Rust for Linux，不是用户态 tokio。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 驱动 UAF 是 CVE 大户。Rust 模块：安全子集 + <code>unsafe</code> 包 C API。缺口：bindings 生成；无标准堆 panic；与 <a href="/cs/livepatch">livepatch</a> 不成熟。本课不把所有 kernel crate 列出。</p><p><span class="marginnote">目标不是用 Rust 重写核心调度。对象是新驱动的记忆安全默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>kbuild 调 rustc → <code>.ko</code> 或内建。对照 <a href="/cs/asan-mechanism">KASAN</a>：动态 vs 静态。对照 seL4：证明 vs 类型。对照 <a href="/cs/chardev-ioctl">ioctl</a>：仍要定义 ABI。</p>',8)),(a(),o(d,null,{default:t(()=>[u(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RS%5B%22Rust%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20BIND%5B%22C%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20BIND%20--%3E%20CORE%5B%22C%20%E5%86%85%E6%A0%B8%E6%A0%B8%E5%BF%83%22%5D%0A%20%20RS%20--%3E%20CHK%5B%22%E5%80%9F%E7%94%A8%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Rust in kernel 把一类内存安全从审查移到编译器，不消除逻辑 bug 与 <code>unsafe</code>。它改变新代码的默认质量。不要写成语言战争。与 <a href="/cs/secure-boot">Secure Boot</a>：模块仍要签名。与 <a href="/cs/ebpf-observability">eBPF</a>：BPF 已是另一条安全沙箱路径。</p><p>工具链版本与内核树绑定是运维税。</p><p>实现上：bindings 由脚本从 C 头生成，C 改布局就破。内核禁止普通 Rust 栈展开 panic。unsafe 块仍要人工审，类型系统不审 DMA 别名。 读法上只引用<a href="/cs/exokernel-libos">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Rust in kernel</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 <code>unsafe</code> 指南。不保证实时路径用 Rust。下一课对照另一宏内核：Windows NT。</p><p>版本字段会变，课序钉的是机制对象「Rust in kernel」，不是某一主线内核的结构体名。 后课默认：新驱动可用 Rust 绑进 Linux。NT 内核对象模型对照，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rust 模块用类型系统减空间错误，经 FFI 调 C。</li><li>不替换整个内核；panic 与分配器要特化。</li><li>Windows NT 对照是下一课。</li><li>出处：Linux rust；kbuild；内存安全课先修。</li></ul>',11))])}const R=n(p,[["render",h]]);export{E as __pageData,R as default};
